/**
 * A Greener Tomorrow - Sidebar Admin & Member Dashboard Script (Vanilla JS v3.0)
 * Features: Left Sidebar Tab Navigation, Mobile Sidebar Drawer Toggle, Quick-Jump Buttons,
 *           Pre-Upload Size Guards, Bcrypt Password Generator Modal, Dynamic Performance Sliders
 */
(function () {
    'use strict';

    document.addEventListener('DOMContentLoaded', function () {
        initAdminSidebarDrawer();
        initAdminTabs();
        initPreUploadGuards();
        initVideoTypeToggle();
        initPasswordModal();
        initPerformanceSliders();
        initLiveSearch();
        initAlertDismiss();
    });

    /* ================= 1. MOBILE SIDEBAR DRAWER TOGGLE ================= */
    function initAdminSidebarDrawer() {
        var sidebar = document.getElementById('adminSidebar');
        var toggleBtn = document.getElementById('adminSidebarToggle');
        var closeBtn = document.getElementById('adminSidebarClose');
        var backdrop = document.getElementById('adminSidebarBackdrop');
        if (!sidebar) return;

        function setSidebarOpen(open) {
            sidebar.classList.toggle('is-open', open);
            if (backdrop) backdrop.classList.toggle('is-active', open);
        }

        if (toggleBtn) {
            toggleBtn.addEventListener('click', function () {
                setSidebarOpen(!sidebar.classList.contains('is-open'));
            });
        }
        if (closeBtn) {
            closeBtn.addEventListener('click', function () {
                setSidebarOpen(false);
            });
        }
        if (backdrop) {
            backdrop.addEventListener('click', function () {
                setSidebarOpen(false);
            });
        }
    }

    /* ================= 2. LEFT SIDEBAR TABS & QUICK JUMP ================= */
    function initAdminTabs() {
        var tabNav = document.querySelector('.admin-tabs-nav');
        if (!tabNav) return;

        var tabButtons = tabNav.querySelectorAll('.tab-btn');
        var tabPanes = document.querySelectorAll('.admin-tab-pane');
        var headingEl = document.getElementById('activeTabTitle');
        var sidebar = document.getElementById('adminSidebar');
        var backdrop = document.getElementById('adminSidebarBackdrop');

        function activateTab(tabId) {
            if (!document.getElementById('tab-' + tabId)) {
                tabId = tabButtons[0] ? tabButtons[0].dataset.tab : 'overview';
            }

            tabButtons.forEach(function (b) {
                var isActive = b.dataset.tab === tabId;
                b.classList.toggle('active', isActive);
                b.setAttribute('aria-selected', isActive ? 'true' : 'false');
            });

            tabPanes.forEach(function (p) {
                var isTarget = p.id === 'tab-' + tabId;
                p.classList.toggle('active', isTarget);
                p.style.display = isTarget ? 'block' : 'none';
                if (isTarget && headingEl && p.dataset.title) {
                    headingEl.textContent = p.dataset.title;
                }
            });

            if (window.innerWidth < 992 && sidebar) {
                sidebar.classList.remove('is-open');
                if (backdrop) backdrop.classList.remove('is-active');
            }

            if (history.replaceState) {
                history.replaceState(null, null, '#' + tabId);
            }
        }

        tabButtons.forEach(function (btn) {
            btn.addEventListener('click', function (e) {
                e.preventDefault();
                activateTab(this.dataset.tab);
            });
        });

        document.querySelectorAll('.js-jump-tab').forEach(function (jumpBtn) {
            jumpBtn.addEventListener('click', function (e) {
                e.preventDefault();
                var targetTab = this.dataset.targetTab;
                if (targetTab) {
                    activateTab(targetTab);
                    window.scrollTo({ top: 0, behavior: 'smooth' });
                }
            });
        });

        var currentHash = window.location.hash.replace('#', '');
        if (currentHash && document.getElementById('tab-' + currentHash)) {
            activateTab(currentHash);
        } else if (tabButtons.length > 0) {
            activateTab(tabButtons[0].dataset.tab);
        }
    }

    /* ================= 3. CLIENT-SIDE PRE-UPLOAD GUARDS ================= */
    function initPreUploadGuards() {
        var fileInputs = document.querySelectorAll('input[type="file"][data-max-mb]');
        fileInputs.forEach(function (input) {
            input.addEventListener('change', function () {
                var maxMb = parseFloat(this.dataset.maxMb) || 15;
                var maxBytes = maxMb * 1024 * 1024;
                var feedbackEl = document.getElementById(this.id + '_feedback') || this.nextElementSibling;

                if (this.files && this.files[0]) {
                    var file = this.files[0];
                    var sizeMb = (file.size / (1024 * 1024)).toFixed(2);

                    if (file.size > maxBytes) {
                        this.value = '';
                        showUploadFeedback(feedbackEl, this, false, 'File exceeds server limit (' + sizeMb + ' MB / Max ' + maxMb + ' MB).');
                    } else {
                        showUploadFeedback(feedbackEl, this, true, 'Ready: ' + file.name + ' (' + sizeMb + ' MB)');
                    }
                }
            });
        });

        function showUploadFeedback(el, input, valid, msg) {
            if (!el || !el.classList || !el.classList.contains('form-feedback')) {
                el = document.createElement('div');
                input.parentNode.appendChild(el);
            }
            el.className = 'form-feedback small mt-1 ' + (valid ? 'text-success' : 'text-danger');
            el.textContent = msg;
        }
    }

    /* ================= 4. VIDEO TYPE TOGGLE ================= */
    function initVideoTypeToggle() {
        var ytRadio = document.getElementById('video_type_youtube');
        var uploadRadio = document.getElementById('video_type_upload');
        var ytContainer = document.getElementById('youtube_field_group');
        var uploadContainer = document.getElementById('direct_upload_field_group');

        if (!ytRadio || !uploadRadio) return;

        function toggleFields() {
            if (ytRadio.checked) {
                if (ytContainer) ytContainer.style.display = 'block';
                if (uploadContainer) uploadContainer.style.display = 'none';
            } else if (uploadRadio.checked) {
                if (ytContainer) ytContainer.style.display = 'none';
                if (uploadContainer) uploadContainer.style.display = 'block';
            }
        }

        ytRadio.addEventListener('change', toggleFields);
        uploadRadio.addEventListener('change', toggleFields);
        toggleFields();
    }

    /* ================= 5. BCRYPT PASSWORD MODAL FOR ADMIN ================= */
    function initPasswordModal() {
        var modal = document.getElementById('passwordResetModal');
        if (!modal) return;

        var modalCloseBtns = modal.querySelectorAll('[data-dismiss="modal"]');
        var modalUserId = modal.querySelector('#modal_user_id');
        var modalUsername = modal.querySelector('#modal_username_display');
        var modalPasswordInput = modal.querySelector('#modal_new_password');
        var generateBtn = modal.querySelector('#btnGeneratePassword');

        document.querySelectorAll('.btn-reset-user-pwd').forEach(function (btn) {
            btn.addEventListener('click', function (e) {
                e.preventDefault();
                if (modalUserId) modalUserId.value = this.dataset.userId;
                if (modalUsername) modalUsername.textContent = this.dataset.username;
                if (modalPasswordInput) modalPasswordInput.value = '';
                modal.classList.add('is-open');
            });
        });

        var closeModal = function () {
            modal.classList.remove('is-open');
        };

        modalCloseBtns.forEach(function (b) { b.addEventListener('click', closeModal); });
        modal.addEventListener('click', function (e) {
            if (e.target === modal || e.target.classList.contains('modal-backdrop')) closeModal();
        });

        if (generateBtn && modalPasswordInput) {
            generateBtn.addEventListener('click', function () {
                var chars = 'abcdefghjkmnpqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789!@#$%&*';
                var pass = '';
                for (var i = 0; i < 14; i++) {
                    pass += chars.charAt(Math.floor(Math.random() * chars.length));
                }
                modalPasswordInput.value = pass;
                modalPasswordInput.type = 'text';
            });
        }
    }

    /* ================= 6. DYNAMIC PERFORMANCE SLIDERS ================= */
    function initPerformanceSliders() {
        var form = document.getElementById('performanceSettingsForm');
        if (!form) return;

        var sliders = form.querySelectorAll('input[type="range"]');
        var liveScoreBadge = document.getElementById('livePerformanceScore');

        sliders.forEach(function (slider) {
            var valueDisplay = document.getElementById(slider.id + '_val');
            slider.addEventListener('input', function () {
                if (valueDisplay) {
                    valueDisplay.textContent = this.value + (slider.dataset.unit || '');
                }
                calculateLiveScore();
            });
        });

        function calculateLiveScore() {
            if (!liveScoreBadge) return;
            var webpQuality = parseInt(document.getElementById('webp_quality')?.value || 82, 10);
            var cacheDays = parseInt(document.getElementById('cache_expiry_days')?.value || 30, 10);
            var lazyAggressive = parseInt(document.getElementById('lazy_aggressiveness')?.value || 85, 10);

            var base = 60;
            var webpScore = (webpQuality >= 75 && webpQuality <= 88) ? 20 : 10;
            var cacheScore = (cacheDays >= 30) ? 15 : 8;
            var lazyScore = (lazyAggressive >= 70) ? 15 : 7;
            var total = Math.min(base + webpScore + cacheScore + lazyScore, 100);

            liveScoreBadge.textContent = total + '/100 A+';
        }
    }

    /* ================= 7. LIVE TABLE SEARCH ================= */
    function initLiveSearch() {
        document.querySelectorAll('[data-table-search]').forEach(function (input) {
            var table = document.getElementById(input.dataset.tableSearch);
            if (!table) return;

            input.addEventListener('keyup', function () {
                var query = this.value.toLowerCase().trim();
                table.querySelectorAll('tbody tr').forEach(function (row) {
                    row.style.display = row.textContent.toLowerCase().indexOf(query) > -1 ? '' : 'none';
                });
            });
        });
    }

    /* ================= 8. ALERT AUTO-DISMISS ================= */
    function initAlertDismiss() {
        document.querySelectorAll('.alert-dismissible').forEach(function (al) {
            setTimeout(function () {
                al.style.transition = 'opacity 0.5s ease';
                al.style.opacity = '0';
                setTimeout(function () { al.remove(); }, 500);
            }, 4500);
        });
    }
})();
